SRC={
'net/minecraft/network/chat/Component.java':'''package net.minecraft.network.chat;import java.util.*;public interface Component{String getString();static MutableComponent translatable(String s){return new MutableComponent(s);}static MutableComponent translatable(String s,Object...a){return new MutableComponent(s+Arrays.toString(a));}}''',
'net/minecraft/network/chat/MutableComponent.java':'''package net.minecraft.network.chat;public class MutableComponent implements Component{String s;public MutableComponent(String s){this.s=s;}public String getString(){return s;}}''',
'net/minecraft/client/gui/GuiGraphics.java':'''package net.minecraft.client.gui;import java.util.*;import net.minecraft.network.chat.Component;public class GuiGraphics{public List<String> words=new ArrayList<>();public int fills;public void fill(int x,int y,int xx,int yy,int c){fills++;}public void drawCenteredString(Font f,Component s,int x,int y,int c){words.add(s.getString());}public int drawString(Font f,Component s,int x,int y,int c,boolean shadow){words.add(s.getString());return 0;}}''',
'net/minecraft/client/gui/components/Button.java':'''package net.minecraft.client.gui.components;import net.minecraft.network.chat.Component;import net.minecraft.client.gui.components.events.GuiEventListener;import net.minecraft.client.gui.narration.NarratableEntry;public class Button implements GuiEventListener,Renderable,NarratableEntry{public interface OnPress{void onPress(Button b);}public OnPress action;public int x,y,w,h;public static Builder builder(Component c,OnPress p){return new Builder(p);}public void press(){action.onPress(this);}public static class Builder{Button b=new Button();Builder(OnPress p){b.action=p;}public Builder bounds(int x,int y,int w,int h){b.x=x;b.y=y;b.w=w;b.h=h;return this;}public Button build(){return b;}}}''',
'net/minecraft/client/gui/screens/Screen.java':'''package net.minecraft.client.gui.screens;import java.util.*;import net.minecraft.client.gui.*;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.components.events.GuiEventListener;import net.minecraft.client.gui.narration.NarratableEntry;import net.minecraft.network.chat.Component;public class Screen{protected int width=800,height=500;protected Font font=new Font();public List<Object> widgets=new ArrayList<>();public boolean closed;protected Screen(Component c){}protected void init(){}public void fixtureInit(){init();}public void renderBackground(GuiGraphics g,int x,int y,float d){}public void render(GuiGraphics g,int x,int y,float d){renderBackground(g,x,y,d);}public void onClose(){closed=true;}public boolean isPauseScreen(){return true;}protected <T extends GuiEventListener & Renderable & NarratableEntry>T addRenderableWidget(T w){widgets.add(w);return w;}}''',
'net/minecraft/client/Minecraft.java':'''package net.minecraft.client;import net.minecraft.client.gui.screens.Screen;public class Minecraft{static final Minecraft INSTANCE=new Minecraft();public Screen screen;public static Minecraft getInstance(){return INSTANCE;}public void setScreen(Screen s){screen=s;}}''',
'dev/settledlands/npc/NpcStatsNetwork.java':'''package dev.settledlands.npc;import java.util.function.Consumer;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;public class NpcStatsNetwork{public static Consumer<Open> opener;public static void setClientOpener(Consumer<Open> f){opener=f;}public record Open(int entityId,long nonceMost,long nonceLeast,int health,int damage,int speed,boolean eligible){}public record Enter(int entityId,long nonceMost,long nonceLeast) implements CustomPacketPayload{public Type<? extends CustomPacketPayload> type(){return null;}}}''',
'dev/settledlands/npc/NpcNet.java':'''package dev.settledlands.npc;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;public class NpcNet{public static CustomPacketPayload last;public static void sendToServer(CustomPacketPayload p){last=p;}}''',
}
TEST='''import dev.settledlands.npc.*;import dev.settledlands.npc.client.NpcStatsScreen;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.Button;import net.minecraft.client.gui.screens.Screen;public class StatsScreenTest{static void ck(boolean b,String s){if(!b)throw new AssertionError(s);}public static void main(String[]a){NpcStatsScreen.install();ck(NpcStatsNetwork.opener!=null,"opener");NpcStatsNetwork.opener.accept(new NpcStatsNetwork.Open(23,123,456,11,9,12,false));Screen s=Minecraft.getInstance().screen;ck(s instanceof NpcStatsScreen&&!s.isPauseScreen(),"screen");s.fixtureInit();ck(s.widgets.size()==1,"button");Button b=(Button)s.widgets.get(0);ck(b.x==320&&b.w==160&&b.h==20,"bounds");GuiGraphics g=new GuiGraphics();s.render(g,0,0,0);String out=g.words.toString();ck(g.fills==3&&out.contains("stats.title")&&out.contains("stats.health_value[11, 22]")&&out.contains("stats.damage_value[9, 90]")&&out.contains("stats.speed_value[12, 120]")&&out.contains("needs_cult"),"draw "+out);b.press();ck(s.closed&&NpcNet.last.equals(new NpcStatsNetwork.Enter(23,123,456)),"opaque request and close");NpcStatsNetwork.opener.accept(new NpcStatsNetwork.Open(8,9,10,10,10,10,true));s=Minecraft.getInstance().screen;g=new GuiGraphics();s.render(g,0,0,0);ck(!g.words.toString().contains("needs_cult"),"eligible warning");System.out.println("Actual stats screen: rows, heart/percent values, warning, nonce button: PASS");}}'''
def main():
 q=argparse.ArgumentParser();q.add_argument('--java',required=True,type=pathlib.Path);q.add_argument('--jar',required=True,type=pathlib.Path);a=q.parse_args()
 with tempfile.TemporaryDirectory(prefix='screen246-') as d:
  root=pathlib.Path(d);src=root/'src';out=root/'classes';gen_api246.main(src)
  # Keep only API silhouettes needed by this screen and its Java test.
  for path in list(src.rglob('*.java')):
   relative=path.relative_to(src).as_posix()
   if relative not in SRC and relative not in ('net/minecraft/client/gui/Font.java','net/minecraft/client/gui/components/Renderable.java','net/minecraft/client/gui/components/events/GuiEventListener.java','net/minecraft/client/gui/narration/NarratableEntry.java','net/minecraft/network/protocol/common/custom/CustomPacketPayload.java','net/minecraft/resources/ResourceLocation.java'):
    path.unlink()
  for name,content in SRC.items():file=src/name;file.parent.mkdir(parents=True,exist_ok=True);file.write_text(content+'\n',encoding='utf8')
  (src/'StatsScreenTest.java').write_text(TEST,encoding='utf8')
  subprocess.run([str(a.java.resolve()),'-jar',str(ROOT/'tools/vendor/ecj-3.46.100.jar'),'-21','-encoding','UTF-8','-g:none','-nowarn','-cp',str(a.jar.resolve()),'-d',str(out),*map(str,sorted(src.rglob('*.java')))],check=True)
  with zipfile.ZipFile(a.jar) as z:
   path='dev/settledlands/npc/client/NpcStatsScreen.class';(out/path).parent.mkdir(parents=True,exist_ok=True);(out/path).write_bytes(z.read(path))
  subprocess.run([str(a.java.resolve()),'-Xshare:off','-Xverify:all','-cp',str(out),'StatsScreenTest'],check=True)
 print('Synthetic screen, graphics, button and packet APIs; no Minecraft client.')
if __name__=='__main__':main()
